"""Client addresses (docs/ratelimit.md, section 7)."""

import ipaddress
import re

_PORT = re.compile(r"[0-9]{1,5}")


def parse_address(text: str):
    """The address of an X-Forwarded-For entry or a peer, or None when it is not one."""
    host = text
    if text.startswith("["):
        end = text.find("]")
        if end < 0:
            return None
        host, rest = text[1:end], text[end + 1:]
        if rest:
            if not rest.startswith(":") or not _PORT.fullmatch(rest[1:]) or int(rest[1:]) > 65535:
                return None
        if ":" not in host:
            return None
    elif text.count(":") == 1:
        host, port = text.split(":")
        if not _PORT.fullmatch(port) or int(port) > 65535:
            return None
    if "%" in host or "/" in host or not re.fullmatch(r"[0-9A-Fa-f:.]+", host):
        return None
    try:
        addr = ipaddress.ip_address(host)
    except ValueError:
        return None
    if addr.version == 6 and addr.ipv4_mapped is not None:
        return addr.ipv4_mapped
    return addr


def in_any(addr, networks) -> bool:
    return any(addr.version == n.version and addr in n for n in networks)


def entries(headers) -> list:
    out = []
    for value in headers.get_all("X-Forwarded-For"):
        out.extend(e.strip(" \t") for e in value.split(","))
    return out


def client_address(request, trusted):
    peer = parse_address(request.peer.strip(" \t"))
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    items = entries(request.headers)
    if not items:
        return peer
    current = peer
    for entry in reversed(items):
        addr = parse_address(entry)
        if addr is None:
            return current
        if not in_any(addr, trusted):
            return addr
        current = addr
    return parse_address(items[0])


def key_text(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 6:
        return str(ipaddress.ip_network((addr, 64), strict=False))
    return str(addr)
