"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.address import client_address, in_any, key_text
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"


class State:
    def __init__(self, config):
        self.limits = config.section("limit", [])
        self.trusted = config.section("clients", ())
        self.buckets = [{} for _ in self.limits]
        self.refused = {l.name: 0 for l in self.limits}
        self.clock = None


def _part(part, ctx, addr):
    if part == "tenant":
        return ctx.tenant
    if part == "client":
        return key_text(addr)
    if part == "route":
        return ctx.route.name
    if part == "method":
        return ctx.request.method
    value = ctx.request.headers.get(part[len("header:"):])
    if value is None:
        return None
    return value.strip(" \t") or None


def setup(config):
    return State(config)


def handle(ctx, st):
    if not st.limits:
        return None
    req = ctx.request
    st.clock = req.ts_ms if st.clock is None else max(st.clock, req.ts_ms)
    now = st.clock
    addr = client_address(req, st.trusted)
    method = req.method.upper()
    covering = []
    for i, lim in enumerate(st.limits):
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and method not in lim.methods:
            continue
        if not isinstance(addr, str) and in_any(addr, lim.exempt):
            continue
        key = tuple(_part(p, ctx, addr) for p in lim.key)
        if any(v is None for v in key):
            continue
        cost = lim.cost_of(method)
        bucket = st.buckets[i].get(key)
        if bucket is None:
            bucket = st.buckets[i][key] = new_state(lim, now)
        bucket.refill(now)
        covering.append((lim, bucket, cost))
    if not covering:
        return None
    refusing = [(l, b, c) for l, b, c in covering if c > l.capacity or not b.allows(c)]
    if not refusing:
        for _, b, c in covering:
            b.charge(c)
        lim, b, _ = min(covering, key=lambda x: x[1].remaining())
        _headers(ctx, lim, b, now)
        return None
    best = None
    best_wait = None
    for l, b, c in refusing:
        wait = math.inf if c > l.capacity else b.wait(c, now)
        if best is None or wait > best_wait:
            best, best_wait = (l, b, c), wait
    for l, _, _ in refusing:
        st.refused[l.name] += 1
    lim, b, _ = best
    _headers(ctx, lim, b, now)
    if best_wait != math.inf:
        ctx.headers["Retry-After"] = str(max(1, math.ceil(Fraction(best_wait) / 1000)))
    return 429


def _headers(ctx, lim, b, now):
    ctx.headers["RateLimit-Limit"] = str(lim.capacity)
    ctx.headers["RateLimit-Remaining"] = str(b.remaining())
    ctx.headers["RateLimit-Reset"] = str(b.reset(now))


def summary(st):
    return {"limited": dict(st.refused)} if st.limits else {}
